# Shared by the cases of this file, sourced as: . {{FIX}}/lib.sh {{ROOT}} {{CLAUDE}} {{FIX}}/{{SID}}
# (the harness root, its .claude folder, a folder of the case's own).
H=$1; C=$2; F=$3
if [ "$(id -u)" = 0 ] && id node >/dev/null 2>&1 && command -v gosu >/dev/null 2>&1 && [ -z "${EVAL_AS_NODE:-}" ]; then
  # Root (the image build) runs the case as node, the user of a workshop, as sync-harness.sh would.
  mkdir -p "$F" && chown node "$F" && exec gosu node env EVAL_AS_NODE=1 bash -c "$BASH_EXECUTION_STRING"
  exit 1
fi
python3 -c 'import yaml' 2>/dev/null || { printf 'ok (skipped: PyYAML is missing)'; exit 0; }
TOOL=$C/skills/workshop-profile/scripts/workshop-profile.py
PROF=$H/profiles; [ -d "$PROF/packs" ] || PROF=$C/harness/profiles
SYNC=$H/../sync-harness.sh; [ -f "$SYNC" ] || SYNC=$(command -v sync-harness.sh 2>/dev/null) || SYNC=""
mkdir -p "$F" || exit 1
STG=$F/stg
GITC=(-c user.email=eval@example.invalid -c user.name=eval -c init.defaultBranch=main)
export HARNESS_STAGING=$STG HARNESS_IMAGE_MANIFEST=$F/none.manifest SKILLS_LEGACY_MANIFEST=$F/none.legacy \
       HARNESS_LEGACY_WORKSPACE=$F/legacy HARNESS_SYNC_SCRIPT=${SYNC:-$F/no-sync.sh}
fail() { printf '%s' "$*"; exit 1; }
need_sync() { [ -n "$SYNC" ] || { printf 'ok (skipped: sync-harness.sh is not reachable from this layout)'; exit 0; }; }
put() { mkdir -p "$(dirname "$STG/$1")" && printf '%s\n' "${2:-$1}" > "$STG/$1"; }
# A staging: the real definitions and switcher, and stand-in files for every pack.
mkstg() {
  mkdir -p "$STG/claude/skills" && cp -r "$PROF" "$STG/profiles" && cp -r "$C/skills/workshop-profile" "$STG/claude/skills/" || exit 1
  put claude/settings.json '{}'; put claude/hooks/probe.sh '#!/bin/bash'; put claude/lib/probe.sh '#!/bin/bash'
  put HARNESS.md; put claude/skills/team-probe/SKILL.md; put references/probe.md
  put claude/CLAUDE.workshop.md '@.claude/harness/HARNESS.md'; put claude/settings.local.seed.json '{}'
  put packs/source/claude/rules/source-space.md
  for p in contrib dev quality release docs-audit usage; do put "packs/$p/claude/skills/$p-probe/SKILL.md"; done
  put packs/usage/claude/skills/token-usage/SKILL.md; put packs/dev/claude/agents/dev-probe.md
  put packs/repo-orkeon/references/repo.yaml 'product: Orkeon'; put packs/repo-orkeon/claude/rules/orkeon-probe.md
  put packs/repo-orkeon-workshop/claude/rules/ws-probe.md
}
mkws() { mkdir -p "$1/teams" || exit 1; }
mkrepo() {   # $1 folder, $2 origin URL: a checkout - one commit, README.md and src.txt tracked
  mkdir -p "$1" && git -C "$1" "${GITC[@]}" init -q && git -C "$1" remote add origin "$2" && printf 'x\n' > "$1/README.md" \
    && printf 'y\n' > "$1/src.txt" && git -C "$1" add README.md src.txt && git -C "$1" "${GITC[@]}" commit -qm init || exit 1
}
mkplain() {   # $1 folder, $2 origin URL: a repository holding nothing but README.md and LICENSE (D87)
  mkdir -p "$1" && git -C "$1" "${GITC[@]}" init -q && git -C "$1" remote add origin "$2" && printf 'x\n' > "$1/README.md" \
    && printf 'MIT\n' > "$1/LICENSE" && git -C "$1" add README.md LICENSE && git -C "$1" "${GITC[@]}" commit -qm init || exit 1
}
wp() { env ORKEON_WORKSHOP="$1" python3 "$TOOL" "${@:2}" 2>&1; }
sy() { env ORKEON_WORKSHOP="$1" bash "$SYNC" "${@:2}" 2>&1 | grep -v setlocale; return "${PIPESTATUS[0]}"; }
# The effective packs a dry run announces, or `refused`.
packs_of() { wp "$@" --dry-run | head -n 1 | sed -n -e 's/.* - packs \([^;]*\)\(;.*\)\{0,1\}\.$/\1/p' -e '/fits here/s/.*/refused/p'; }
table() { local p out=""; for p in user contrib dev release docs all; do out="$out$p=$(packs_of "$1" "$p")|"; done; printf '%s' "$out"; }
# Every path and its content under a folder (.git aside): equal before and after means nothing written.
snap() { (cd "$1" && find . -path ./.git -prune -o -type f -print0 | LC_ALL=C sort -z | xargs -0 -r md5sum; find . -path ./.git -prune -o -print | LC_ALL=C sort) | md5sum; }

cases.cmd:
L={{ROOT}}/../orkeon-mcp.sh; [ -f "$L" ] || L=$(command -v orkeon-mcp 2>/dev/null) || { printf 'ok (skipped: orkeon-mcp is not reachable from this layout)'; exit 0; }
F={{FIX}}/{{SID}}; mkdir -p "$F/bin" "$F/w"
printf '#!/bin/sh\nif [ "$1 $2" = "run --list-tools" ]; then printf "%%s\\n" codebase_search index_codebase csv_reader web_search file_write shell_command human_input; exit 0; fi\nprintf "ARGS=%%s\\n" "$*"; env | grep "^ORKEON_Orkeon__FileSystem__Mounts"\n' > "$F/bin/orkeon"; chmod +x "$F/bin/orkeon"
run() { env -u TAVILY_API_KEY -u ORKEON_TAVILY_API_KEY -u BRAVE_API_KEY -u WORKSHOP_MCP_TOOLS -u WORKSHOP_MCP_EXTRA_TOOLS PATH="$F/bin:$PATH" CLAUDE_PROJECT_DIR="$F/w" "$@"; }
a=$(run bash "$L" --print-tools 2>/dev/null | tr '\n' ' '); [ "$a" = 'index_codebase codebase_search csv_reader ' ] || { printf 'BAD-default:%s' "$a"; exit 1; }
b=$(run env TAVILY_API_KEY=k bash "$L" --print-tools 2>/dev/null | tr '\n' ' '); [ "$b" = 'index_codebase codebase_search csv_reader web_search ' ] || { printf 'BAD-key:%s' "$b"; exit 1; }
c=$(run bash "$L" --print-tools 2>&1 >/dev/null | grep -c 'is not a tool of this Orkeon: left out'); [ "$c" -gt 10 ] || { printf 'BAD-lines:%s' "$c"; exit 1; }
d=$(run env WORKSHOP_MCP_TOOLS=all bash "$L" --crew x.yaml 2>/dev/null | tr '\n' ' '); w=$(cd "$F/w" && pwd -P); [ "$d" = "ARGS=mcp serve --allow-external-mounts --crew x.yaml ORKEON_Orkeon__FileSystem__Mounts__90=$w:/workspace:rw " ] || { printf 'BAD-all:%s' "$d"; exit 1; }
e=$(run env WORKSHOP_MCP_TOOLS=csv_reader,human_input bash "$L" 2>/dev/null | head -n 1); [ "$e" = 'ARGS=mcp serve --allow-external-mounts --tools csv_reader' ] || { printf 'BAD-list:%s' "$e"; exit 1; }
printf ok

L={{ROOT}}/../orkeon-mcp.sh; [ -f "$L" ] || L=$(command -v orkeon-mcp 2>/dev/null) || { printf 'ok (skipped: orkeon-mcp is not reachable from this layout)'; exit 0; }
command -v jq >/dev/null 2>&1 || { printf 'ok (skipped: jq is missing)'; exit 0; }
F={{FIX}}/{{SID}}; mkdir -p "$F/bin" "$F/w"
# A stand-in orkeon whose server writes what Orkeon 1.2.0 to 4709278 write: null beside the result and the error,
# null optional fields, a tool answer holding the text "error":null, a parse error's answer whose id is null
# (which JSON-RPC requires: it stays), and a line that is no JSON.
cat > "$F/bin/orkeon" <<'EOS'
#!/bin/sh
if [ "$1 $2" = "run --list-tools" ]; then echo csv_reader; exit 0; fi
if [ "$1" = --version ]; then echo "orkeon 1.2.0+a9f3878aca94"; exit 0; fi
cat <<'EOJ'
{"jsonrpc":"2.0","result":{"protocolVersion":"2025-06-18","capabilities":{"tools":{"listChanged":true}}},"error":null,"id":1}
{"jsonrpc":"2.0","result":{"tools":[],"nextCursor":null},"error":null,"id":2}
{"jsonrpc":"2.0","result":{"content":[{"type":"text","text":"{\"error\":null,\"rows\":[1,null]}","mimeType":null,"data":null}],"isError":false},"error":null,"id":3}
{"jsonrpc":"2.0","result":null,"error":{"code":-32601,"message":"Method not found: nope","data":null},"id":"s4"}
{"jsonrpc":"2.0","result":null,"error":{"code":-32700,"message":"Failed to parse JSON-RPC request","data":null},"id":null}
a line that is no JSON
EOJ
EOS
chmod +x "$F/bin/orkeon"
out=$(env -u WORKSHOP_MCP_TOOLS -u WORKSHOP_MCP_EXTRA_TOOLS PATH="$F/bin:$PATH" CLAUDE_PROJECT_DIR="$F/w" bash "$L" </dev/null 2>/dev/null)
want='{"jsonrpc":"2.0","result":{"protocolVersion":"2025-06-18","capabilities":{"tools":{"listChanged":true}}},"id":1}
{"jsonrpc":"2.0","result":{"tools":[]},"id":2}
{"jsonrpc":"2.0","result":{"content":[{"type":"text","text":"{\"error\":null,\"rows\":[1,null]}"}],"isError":false},"id":3}
{"jsonrpc":"2.0","error":{"code":-32601,"message":"Method not found: nope"},"id":"s4"}
{"jsonrpc":"2.0","error":{"code":-32700,"message":"Failed to parse JSON-RPC request"},"id":null}
a line that is no JSON'
[ "$out" = "$want" ] || { printf 'BAD:%s' "$out"; exit 1; }
printf ok

L={{ROOT}}/../orkeon-mcp.sh; [ -f "$L" ] || L=$(command -v orkeon-mcp 2>/dev/null) || { printf 'ok (skipped: orkeon-mcp is not reachable from this layout)'; exit 0; }
F={{FIX}}/{{SID}}; mkdir -p "$F/bin" "$F/w"
# A stand-in orkeon that prints the version it is given and writes lines with null members on purpose.
cat > "$F/bin/orkeon" <<'EOS'
#!/bin/sh
if [ "$1 $2" = "run --list-tools" ]; then echo csv_reader; exit 0; fi
if [ "$1" = --version ]; then [ -n "$STANDIN_VERSION" ] && echo "orkeon $STANDIN_VERSION"; exit 0; fi
cat <<'EOJ'
{"jsonrpc":"2.0","result":{"content":[],"structuredContent":{"row":null}},"id":3}
{"jsonrpc":"2.0","error":{"code":-32700,"message":"Failed to parse JSON-RPC request"},"id":null}
EOJ
EOS
chmod +x "$F/bin/orkeon"
run() { env -u WORKSHOP_MCP_TOOLS -u WORKSHOP_MCP_EXTRA_TOOLS STANDIN_VERSION="$1" PATH="$F/bin:$PATH" CLAUDE_PROJECT_DIR="$F/w" bash "$L" </dev/null 2>/dev/null; }
raw='{"jsonrpc":"2.0","result":{"content":[],"structuredContent":{"row":null}},"id":3}
{"jsonrpc":"2.0","error":{"code":-32700,"message":"Failed to parse JSON-RPC request"},"id":null}'
filtered='{"jsonrpc":"2.0","result":{"content":[],"structuredContent":{}},"id":3}
{"jsonrpc":"2.0","error":{"code":-32700,"message":"Failed to parse JSON-RPC request"},"id":null}'
r=""
for v in 1.3.0-src.20261118.g1b480bd+1b480bd1c7c2 1.3.0 1.4.0-dev.12; do [ "$(run "$v")" = "$raw" ] || r="$r raw:$v"; done
if command -v jq >/dev/null 2>&1; then
  for v in 1.2.0 1.2.0-src.20261117.g4709278 ""; do [ "$(run "$v")" = "$filtered" ] || r="$r filtered:${v:-none}"; done
fi
[ -z "$r" ] || { printf 'BAD:%s' "$r"; exit 1; }
command -v jq >/dev/null 2>&1 || { printf 'ok (skipped: jq is missing, the filtered half did not run)'; exit 0; }
printf ok
